import * as vscode from "vscode";
import * as fs from "fs";
import * as path from "path";
import { expandItemsByLevel } from "./expandItemsByLevel";
import { expandLocalizationByLevel } from "./expandLocalizationByLevel";
import { localizeBaseItems } from "./localizeBaseItems";
import { syncBaseAbilityValues } from "./syncBaseAbilityValues";
import { generateDerivedItemLua } from "./generateDerivedItemLua";

type KVValue = string | KVObject;
type KVObject = { [k: string]: KVValue };

type PairConfig = {
    name: string;
    statsPath: string;
    rawPath: string;
};

type FieldMeta = {
    base?: string;                 // ç”¨äºŽæŸ¥æœ¬åœ°åŒ–çš?base key
    fallbackLocalized?: string;    // æŸ¥ä¸åˆ°æœ¬åœ°åŒ–æ—¶çš„å…œåº•
};

type PluginConfig = {
    pairs: PairConfig[];
    fieldTable: Record<string, FieldMeta>;
    fieldTable2: Record<string, FieldMeta>;
    localizationFile: string;
    localizationLookupKeys?: string[];
    ensureLeadingPlusSpace?: boolean;
    Level?: Record<string, unknown>;
};

function buildAbilityVariableKey(field: string): {
    isPct: boolean;        // â€œåŒ…å?Pctâ€?å°±æŒ‰ç™¾åˆ†æ¯”æ˜¾ç¤?
    varKey: string;        // projectiledamageflat / critchangepct
    localeVarKey: string;  // dota_ability_variable_projectiledamageflat
} {
    // è§„åˆ™ï¼šå­—æ®µååªè¦åŒ…å« Pctï¼Œå°±æ˜¾ç¤ºä¸?+% ä¸­æ–‡å?
    const isPct = /Pct/.test(field);

    // åŽ»æŽ‰æœ€åŽä¸€ä¸?_Flat / _Pctï¼ˆåªå¤„ç†æœ«å°¾ï¼Œä¸è¯¯ä¼¤ä¸­é—´ï¼?
    const base = field.replace(/_(Flat|Pct)$/i, "");

    const varKey = base.toLowerCase();
    const localeVarKey = "dota_ability_variable_" + varKey;

    return { isPct, varKey, localeVarKey };
}

function stripComments(input: string): string {
    // ç§»é™¤ //... è¡Œæ³¨é‡?+ /*...*/ å—æ³¨é‡?
    // æ³¨æ„ï¼šè¿™æ˜¯ç®€åŒ–ç‰ˆï¼Œè¶³å¤Ÿå¤„ç†å…¸åž?KV æ–‡ä»¶ï¼ˆä¸åšå­—ç¬¦ä¸²å†…æ³¨é‡Šè¯†åˆ«ï¼‰
    const noBlock = input.replace(/\/\*[\s\S]*?\*\//g, "");
    return noBlock.replace(/\/\/.*$/gm, "");
}

type Token =
    | { t: "{" | "}"; idx?: number }
    | { t: "str"; v: string; idx?: number };

function tokenizeKVWithStripped(input: string): { tokens: Token[]; stripped: string } {
    const s = stripComments(input);
    const tokens: Token[] = [];
    let i = 0;

    const isWS = (c: string) => c === " " || c === "\t" || c === "\r" || c === "\n";

    while (i < s.length) {
        const c = s[i];

        if (isWS(c)) { i++; continue; }
        if (c === "{" || c === "}") { tokens.push({ t: c, idx: i }); i++; continue; }

        if (c === "\"") {
            const start = i;
            i++; // skip opening "
            let out = "";
            while (i < s.length) {
                const ch = s[i];
                if (ch === "\\") {
                    const next = s[i + 1];
                    if (next) { out += next; i += 2; continue; }
                    i++; continue;
                }
                if (ch === "\"") { i++; break; }
                out += ch;
                i++;
            }
            tokens.push({ t: "str", v: out, idx: start });
            continue;
        }

        // ?????????????????????token???????????????????????????
        let out = "";
        const start = i;
        while (i < s.length) {
            const ch = s[i];
            if (isWS(ch) || ch === "{" || ch === "}") break;
            out += ch;
            i++;
        }
        if (out.length > 0) tokens.push({ t: "str", v: out, idx: start });
    }

    return { tokens, stripped: s };
}

function tokenizeKV(input: string): Token[] {
    return tokenizeKVWithStripped(input).tokens;
}

function parseKV(tokens: Token[]): KVObject {
    let idx = 0;

    function expectStr(): string {
        const tk = tokens[idx];
        if (!tk || tk.t !== "str") throw new Error(`Expected string at token ${idx}`);
        idx++;
        return tk.v;
    }

    function parseObject(): KVObject {
        const obj: KVObject = {};
        while (idx < tokens.length) {
            const tk = tokens[idx];
            if (tk.t === "}") { idx++; break; }

            const key = expectStr();
            const next = tokens[idx];
            if (!next) throw new Error(`Unexpected EOF after key: ${key}`);

            if (next.t === "{") {
                idx++; // consume {
                obj[key] = parseObject();
            } else if (next.t === "str") {
                const val = expectStr();
                obj[key] = val;
            } else {
                throw new Error(`Unexpected token after key ${key} at ${idx}`);
            }
        }
        return obj;
    }

    // é¡¶å±‚å¯èƒ½æ˜¯ä¸€ä¸ªæ ¹å¯¹è±¡ï¼ˆå¸¸è§ï¼š "Items" { ... } ï¼‰ä¹Ÿå¯èƒ½ç›´æŽ¥å°±æ˜¯å¤šæ®µ key
    const root: KVObject = {};
    while (idx < tokens.length) {
        const tk = tokens[idx];
        if (tk.t === "}") throw new Error("Unmatched '}' at top level");
        const k = expectStr();
        const n = tokens[idx];
        if (!n) throw new Error(`Unexpected EOF after key: ${k}`);
        if (n.t === "{") {
            idx++;
            root[k] = parseObject();
        } else if (n.t === "str") {
            root[k] = expectStr();
        } else {
            throw new Error(`Unexpected token after top key ${k}`);
        }
    }
    return root;
}

function kvToString(obj: KVObject, indent = 0): string {
    const pad = (n: number) => "\t".repeat(n);
    const quote = (v: string) => `"${v.replace(/\\/g, "\\\\").replace(/"/g, "\\\"")}"`;

    const keys = Object.keys(obj);

    let out = "";
    for (const k of keys) {
        const v = obj[k];
        if (typeof v === "string") {
            out += `${pad(indent)}${quote(k)}\t\t${quote(v)}\n`;
        } else {
            out += `${pad(indent)}${quote(k)}\n`;
            out += `${pad(indent)}{\n`;
            out += kvToString(v, indent + 1);
            out += `${pad(indent)}}\n`;
        }
    }
    return out;
}

function readKVFile(absPath: string): KVObject {
    const text = fs.readFileSync(absPath, "utf8");
    const { tokens, stripped } = tokenizeKVWithStripped(text);
    try {
        return parseKV(tokens);
    } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        const m = /token (\d+)/.exec(msg);
        if (m) {
            const ti = Number(m[1]);
            const tk = tokens[ti];
            if (tk && typeof tk.idx === "number") {
                const before = stripped.slice(0, tk.idx);
                const line = before.split("\n").length;
                const lastNl = before.lastIndexOf("\n");
                const col = tk.idx - (lastNl >= 0 ? lastNl : -1);
                const snippet = stripped.slice(tk.idx, tk.idx + 80).replace(/\n/g, "\\n");
                throw new Error(msg + " in " + absPath + " (line " + line + ", col " + col + " in stripped text). Near: " + snippet);
            }
        }
        throw err;
    }
}

function writeKVFile(absPath: string, obj: KVObject): void {
    const content = kvToString(obj, 0);
    fs.writeFileSync(absPath, content, "utf8");
}

function isObject(v: KVValue | undefined): v is KVObject {
    return typeof v === "object" && v !== null;
}


function formatNumber(n: number): string {
    // è¾“å‡ºå°½é‡â€œKV å‹å¥½â€ï¼šåŽ»æŽ‰æ— æ„ä¹‰çš„å°æ•° 0
    if (!isFinite(n)) return String(n);
    const s = n.toFixed(6); // è¶³å¤Ÿè¦†ç›– 0.01 ç¼©æ”¾åŽçš„ç²¾åº¦
    return s.replace(/\.0+$/, "").replace(/(\.\d*?)0+$/, "$1");
}

function shouldScaleByPoint01(fieldName: string): boolean {
    // è§„åˆ™ï¼?
    // 1) ä»»æ„åŒ…å« Pct çš„å­—æ®µï¼ˆä¾‹å¦‚ AttackDamagePct_Pct / FinalDamagePct_Pct / CritPct ç­‰ï¼‰æŒ?0.01 ç¼©æ”¾
    // 2) ç‰¹å®š Flat å­—æ®µåŒæ ·æŒ?0.01 ç¼©æ”¾ï¼ˆé…ç½®å¡«ä¸‡åˆ†æ¯?/ IAS ç‚¹æ•° / å†·å´ç‚¹æ•°ï¼?
    if (/Pct/.test(fieldName)) return true;
    return fieldName === "AttackSpeed_Flat"
        || fieldName === "ProjectileCooldown_Flat"
        || fieldName === "SkillCooldown_Flat";
}

function transformValue(fieldName: string, raw: string): string {
    if (!shouldScaleByPoint01(fieldName)) return raw.trim();

    const tokens = raw.trim().split(/\s+/);
    const scaled = tokens.map(t => {
        const num = Number(t);
        if (Number.isFinite(num)) {
            return formatNumber(num * 0.01);
        }
        return t;
    });
    return scaled.join(" ");
}

function buildTooltipValueForField(fieldName: string, locKV: KVObject): string | undefined {
    // ç‰¹ä¾‹ï¼šLevel çš?tooltip ä¸æ˜¯ +$levelï¼Œè€Œæ˜¯ "$level"ï¼ˆä½ çŽ°æœ‰æ–‡ä»¶å°±æ˜¯è¿™æ ·ï¼?
    if (fieldName === "Level") return "å¡ç‰Œé˜¶çº§ï¼?;

    const { isPct, varKey, localeVarKey } = buildAbilityVariableKey(fieldName);

    if (!isPct) {
        // é?Pctï¼?+$projectiledamageflat"
        return `+$${varKey}`;
    }

    // Pctï¼?+% æš´å‡»çŽ? â€”â€?ä¸­æ–‡åæ¥è‡?dota_ability_variable_xxx
    const cn = locKV[localeVarKey];
    if (typeof cn === "string" && cn.trim().length > 0) {
        return `+% ${cn.trim()}`;
    }

    // æ‰¾ä¸åˆ°ä¸­æ–‡å˜é‡åæ—¶å…œåº•ï¼ˆé¿å…å†™å…¥ç©ºå­—ç¬¦ä¸²ï¼?
    return `+% ${varKey}`;
}


function findConfigFile(root: string, name: string): string | null {
    const entries = fs.readdirSync(root, { withFileTypes: true });
    for (const e of entries) {
        const full = path.join(root, e.name);
        if (e.isFile() && e.name === name) {
            return full;
        }
        if (e.isDirectory()) {
            const found = findConfigFile(full, name);
            if (found) return found;
        }
    }
    return null;
}

function loadConfig(workspaceRoot: string): PluginConfig {
    const cfgName = "dzsj.kv-sync.json";

    const found = findConfigFile(workspaceRoot, cfgName);
    if (!found) {
        throw new Error(`Missing config: ${path.join(workspaceRoot, cfgName)}`);
    }

    return JSON.parse(fs.readFileSync(found, "utf8")) as PluginConfig;
}

function insertLocalizationByIndex(
    locText: string,
    insertIndexRef: { value: number },
    entries: { key: string; value: string }[]
): string {
    if (entries.length === 0) return locText;

    const tokensMatch = locText.match(/"Tokens"\s*\{([\s\S]*?)\n\}/);
    if (!tokensMatch) return locText;

    const tokensBody = tokensMatch[1];
    const tokensBodyStart =
        tokensMatch.index! + tokensMatch[0].indexOf("{") + 1;
    const tokensBodyEnd = tokensBodyStart + tokensBody.length;

    const lines = tokensBody.split("\n");

    const insertLines = entries.map(e =>
        `        "${e.key}" "${e.value}"`
    );

    const idx = insertIndexRef.value;

    const newLines = [
        ...lines.slice(0, idx),
        ...insertLines,
        ...lines.slice(idx),
    ];

    insertIndexRef.value += insertLines.length;

    const newTokensBody = newLines.join("\n");

    return (
        locText.slice(0, tokensBodyStart) +
        newTokensBody +
        locText.slice(tokensBodyEnd)
    );
}


export function activate(context: vscode.ExtensionContext) {
    const disposable = vscode.commands.registerCommand("dzsjKvSync.run", async () => {
        const folders = vscode.workspace.workspaceFolders;
        if (!folders || folders.length === 0) {
            vscode.window.showErrorMessage("No workspace folder opened.");
            return;
        }
        const root = folders[0].uri.fsPath;

        function getMaxLevelFromStatsItem(itemStats: KVObject): number {
            for (const v of Object.values(itemStats)) {
                if (typeof v === "string") {
                    const tokens = v.trim().split(/\s+/);
                    if (tokens.length > 1) {
                        return tokens.length;
                    }
                }
            }
            return 1;
        }


        try {
            const cfg = loadConfig(root);
            const locPath = path.join(root, cfg.localizationFile);
            const locKV = fs.existsSync(locPath) ? readKVFile(locPath) : ({} as KVObject);
            let locText = fs.existsSync(locPath)
                ? fs.readFileSync(locPath, "utf8")
                : "";

            for (const pair of cfg.pairs) {
                const statsAbs = path.join(root, pair.statsPath);
                const rawAbs = path.join(root, pair.rawPath);

                if (!fs.existsSync(statsAbs)) throw new Error(`Missing stats file: ${statsAbs}`);
                if (!fs.existsSync(rawAbs)) throw new Error(`Missing raw file: ${rawAbs}`);

                const statsKV = readKVFile(statsAbs);
                const rawKV = readKVFile(rawAbs);

                // å…¼å®¹ä¸¤ç§å½¢æ€ï¼š
                // A) é¡¶å±‚ç›´æŽ¥æ˜?item blocks: "item_x" { ... }
                // B) æœ‰æ ¹èŠ‚ç‚¹åŒ…è£¹: "Items" { "item_x" { ... } }
                function detectRootItems(kv: KVObject): KVObject {
                    // å¦‚æžœåªæœ‰ä¸€ä¸ªé¡¶å±?key ä¸?value æ˜?objectï¼Œå°±å½“æ ¹
                    const ks = Object.keys(kv);
                    if (ks.length === 1 && isObject(kv[ks[0]])) return kv[ks[0]] as KVObject;
                    return kv;
                }

                const statsItems = detectRootItems(statsKV);
                const rawItems = detectRootItems(rawKV);

                // === æ–°å¢žï¼šè¯»å?stats åŽŸæ–‡ tokensï¼Œç”¨äºŽæå?BonusAttribute çš„åŽŸå§‹é¡ºåº?===
                const statsText = fs.readFileSync(statsAbs, "utf8");
                const statsTokens = tokenizeKV(statsText);

                function getBonusAttributeOrder(itemName: string): string[] {
                    const order: string[] = [];

                    // æ‰¾åˆ° "itemName" { ... }ï¼Œè¿›å…¥åŽå†æ‰¾åˆ?"BonusAttribute" { ... } æ”¶é›†å…?key é¡ºåº
                    let i = 0;
                    while (i < statsTokens.length) {
                        const tk = statsTokens[i];

                        if (tk.t === "str" && tk.v === itemName) {
                            const next = statsTokens[i + 1];
                            if (next && next.t === "{") {
                                i += 2; // è¿›å…¥ item block
                                let depth = 1;

                                while (i < statsTokens.length && depth > 0) {
                                    const cur = statsTokens[i];

                                    if (cur.t === "{") { depth++; i++; continue; }
                                    if (cur.t === "}") { depth--; i++; continue; }

                                    // item é¡¶å±‚ (depth==1)ï¼šæ‰¾ BonusAttribute
                                    if (depth === 1 && cur.t === "str" && cur.v === "BonusAttribute") {
                                        const after = statsTokens[i + 1];
                                        if (after && after.t === "{") {
                                            i += 2; // è¿›å…¥ BonusAttribute block
                                            let bDepth = 1;

                                            while (i < statsTokens.length && bDepth > 0) {
                                                const bt = statsTokens[i];

                                                if (bt.t === "{") { bDepth++; i++; continue; }
                                                if (bt.t === "}") { bDepth--; i++; continue; }

                                                // BonusAttribute é¡¶å±‚ (bDepth==1)ï¼šè¯»å?key "value"
                                                if (bDepth === 1 && bt.t === "str") {
                                                    const key = bt.v;
                                                    const valTk = statsTokens[i + 1];
                                                    if (valTk && valTk.t === "str") {
                                                        order.push(key);
                                                        i += 2;
                                                        continue;
                                                    }
                                                }

                                                i++;
                                            }
                                            // BonusAttribute å¤„ç†å®Œç›´æŽ¥è¿”å›?
                                            return order;
                                        }
                                    }

                                    i++;
                                }

                                break;
                            }
                        }

                        i++;
                    }

                    return order;
                }


                const rawItemOrder = Object.keys(statsItems).filter(
                    k => typeof statsItems[k] === "object" && typeof rawItems[k] === "object"
                );

                if (rawItemOrder.length === 0) {
                    throw new Error(`[${pair.name}] No item blocks found in raw file (rawItems is empty). Check root structure / detectRootItems.`);
                }

                syncBaseAbilityValues({
                    pairName: pair.name,
                    statsItems,
                    rawItems,
                    fieldTable: cfg.fieldTable,
                    fieldTable2: cfg.fieldTable2,
                    levelConfig: cfg.Level,
                    transformValue,
                });

                // === æœ¬åœ°åŒ–æ’å…¥ä½ç½®ï¼šå¿…é¡»æ˜¯åŒä¸€ä¸?refï¼Œéšæ’å…¥é€’å¢ž ===
                let insertIndexRef: { value: number } | undefined;

                const maxLevelMap: Record<string, number> = {};

                // é€?itemï¼šå…ˆ baseï¼Œå†æ´¾ç”Ÿï¼ˆä¿è¯è¾“å‡ºé¡ºåºç¬¦åˆè®¾è®¡ï¼‰
                for (const itemName of rawItemOrder) {
                    const itemStats = statsItems[itemName] as KVObject;

                    const maxLevel = getMaxLevelFromStatsItem(itemStats);
                    maxLevelMap[itemName] = maxLevel;

                    const baseLoc = localizeBaseItems({
                        pairName: pair.name,
                        rawItemOrder: [itemName], // â˜?åªå¤„ç†å½“å‰?item
                        statsItems,
                        rawItems,
                        locKV,
                        locText,
                        insertLocalizationByIndex,
                        buildTooltipValueForField,
                        getBonusAttributeOrder,
                        insertIndexRef,            // â˜?å¤ç”¨å…¨å±€æ’å…¥ä½ç½®
                    });

                    locText = baseLoc.locText;

                    // â˜?ç¬¬ä¸€æ¬¡å®šä½åˆ° Tokens æ’å…¥ç‚¹åŽï¼ŒåŽç»­æŒç»­å¤ç”¨å¹¶é€’å¢ž
                    if (!insertIndexRef && baseLoc.insertIndexRef) {
                        insertIndexRef = baseLoc.insertIndexRef;
                    }

                    // æ´¾ç”Ÿæœ¬åœ°åŒ–ç´§è·Ÿåœ¨è¯?item çš?base åŽé¢
                    if (insertIndexRef) {
                        locText = expandLocalizationByLevel({
                            rawItemOrder: [itemName], // â˜?åªæ´¾ç”Ÿå½“å‰?item
                            rawItems,
                            statsItems,
                            locKV,
                            locText,
                            insertIndexRef,
                            insertLocalizationByIndex,
                            buildTooltipValueForField,
                            maxLevelMap,
                        });
                    }

                    const baseLuaPath = path.join(
                        root,
                        "game/dzsj/scripts/vscripts/abilities",
                        `${itemName}.lua`
                    );

                    for (let lvl = 1; lvl <= maxLevel; lvl++) {
                        generateDerivedItemLua(baseLuaPath, lvl);
                    }
                }

                // æœ€åŽå†ç”Ÿæˆ raw çš„æ´¾ç”?itemsï¼ˆæœ¬åœ°åŒ–é¡ºåºå·²ä¿è¯æ­£ç¡®ï¼‰
                expandItemsByLevel(rawItems, rawItemOrder, maxLevelMap);


                writeKVFile(rawAbs, rawKV);
            }

            // å†™å›žæœ¬åœ°åŒ?
            fs.writeFileSync(locPath, locText, "utf8");

        } catch (e: any) {
            vscode.window.showErrorMessage(`DZSJ KV Sync failed: ${e?.message ?? String(e)}`);
        }
    });

    context.subscriptions.push(disposable);
}

export function deactivate() { }

