type KVValue = string | KVObject;
type KVObject = { [k: string]: KVValue };

export function localizeBaseItems(params: {
    pairName: string;
    rawItemOrder: string[];
    statsItems: KVObject;
    rawItems: KVObject;
    locKV: KVObject;
    locText: string;
    insertLocalizationByIndex: Function;
    buildTooltipValueForField: Function;
    getBonusAttributeOrder: (item: string) => string[];
    insertIndexRef?: { value: number };
}): {
    locText: string;
    insertIndexRef: { value: number } | null;
} {
    const {
        rawItemOrder,
        statsItems,
        rawItems,
        locKV,
        insertLocalizationByIndex,
        buildTooltipValueForField,
        getBonusAttributeOrder,
        insertIndexRef: externalInsertIndexRef,
    } = params;

    let locText = params.locText;

    let insertIndexRef: { value: number } | null = externalInsertIndexRef ?? null;

    // 只有在外部没传时，才为“当前 item”计算锚点
    if (!insertIndexRef) {
        const firstItem = rawItemOrder[0];
        const bonusOrder = getBonusAttributeOrder(firstItem);

        if (bonusOrder.length > 0) {
            const anchorKey =
                `DOTA_Tooltip_Ability_${firstItem}_${bonusOrder[0]}`;

            const m = locText.match(/"Tokens"\s*\{([\s\S]*?)\n\}/);
            if (m) {
                const lines = m[1].split("\n");
                for (let i = 0; i < lines.length; i++) {
                    if (lines[i].includes(`"${anchorKey}"`)) {
                        insertIndexRef = { value: i + 1 };
                        break;
                    }
                }
            }
        }
    }

    // 如果还是没锚点，直接返回（行为与原设计一致）
    if (!insertIndexRef) {
        return { locText, insertIndexRef: null };
    }

    // === 原有属性区本地化（不变）===
    for (const itemName of rawItemOrder) {
        const statsItem = statsItems[itemName];
        const rawItem = rawItems[itemName];
        if (typeof statsItem !== "object" || typeof rawItem !== "object") continue;

        const abilityValues = rawItem["AbilityValues"] as KVObject;
        const locEntries: { key: string; value: string }[] = [];

        for (const fieldName of Object.keys(abilityValues)) {
            if (fieldName === "Level") {
                // allowed
            } else if (
                typeof statsItem["BonusAttribute"] === "object" &&
                !(fieldName in statsItem["BonusAttribute"])
            ) {
                continue;
            }

            const locKey =
                `DOTA_Tooltip_Ability_${itemName}_${fieldName}`;

            if (locText.includes(`"${locKey}"`)) continue;

            const val = buildTooltipValueForField(fieldName, locKV);
            if (!val) continue;

            locEntries.push({ key: locKey, value: val });
        }

        if (locEntries.length > 0) {
            locText = insertLocalizationByIndex(
                locText,
                insertIndexRef,
                locEntries
            );
        }
    }

    return { locText, insertIndexRef };
}

