    const end = start + body.length;

    return locText.slice(0, start) + result.join("\n") + locText.slice(end);
}


export function expandLocalizationByLevel(params: {
    rawItemOrder: string[];
    rawItems: KVObject;
    statsItems: KVObject;
    locKV: KVObject;
    locText: string;
    insertIndexRef: { value: number };
    insertLocalizationByIndex: Function;
    buildTooltipValueForField: Function;
    maxLevelMap: Record<string, number>;
}): string {
    const {
        rawItemOrder,
        rawItems,
        statsItems,
        locKV,
        insertIndexRef,
        insertLocalizationByIndex,
        buildTooltipValueForField,
        maxLevelMap,
    } = params;

    let locText = params.locText;

    for (const itemName of rawItemOrder) {
        const rawItem = rawItems[itemName];
        const statsItem = statsItems[itemName];

        // === 类型收窄（必须）===
        if (!isObject(rawItem) || !isObject(statsItem)) continue;

        const avVal = rawItem["AbilityValues"];
        if (!isObject(avVal)) continue;

        const av = avVal;

        const maxLevel = maxLevelMap[itemName] ?? 1;
        if (maxLevel <= 1) continue;

        const bonusVal = statsItem["BonusAttribute"];

        // === 1) 属性区 _1~_N ===
        for (let lvl = 1; lvl <= maxLevel; lvl++) {
            const entries: { key: string; value: string }[] = [];

            for (const field of Object.keys(av)) {
                if (field === "Level") {
                    // ok
                } else if (isObject(bonusVal)) {
                    if (!(field in bonusVal)) continue;
                }

                const locKey =
                    `DOTA_Tooltip_Ability_${itemName}_${lvl}_${field}`;

                if (locText.includes(`"${locKey}"`)) continue;

                const val = buildTooltipValueForField(field, locKV);
                if (!val) continue;

                entries.push({ key: locKey, value: val });
            }

            if (entries.length > 0) {
                locText = insertLocalizationByIndex(
                    locText,
                    insertIndexRef,
                    entries
                );
            }
        }

        // === 2) Name / Desc / Lore / Summary（复制存在的）===
        const sections = [
            "",
            "_Description",
            "_Lore",
            "_SummaryDescription",
            "_SummaryDescription_LevelUp",
        ];

        for (const suf of sections) {
            const baseKey =
                `DOTA_Tooltip_Ability_${itemName}${suf}`;

            const m = locText.match(
                new RegExp(`"${baseKey}"\\s+"([^"]*)"`)
            );
            if (!m) continue;

            const value = m[1];
            const newLines: string[] = [];

            for (let lvl = 1; lvl <= maxLevel; lvl++) {
                const newKey =
                    `DOTA_Tooltip_Ability_${itemName}_${lvl}${suf}`;

                if (locText.includes(`"${newKey}"`)) continue;

                newLines.push(
                    `        "${newKey}" "${value}"`
                );
            }

            if (newLines.length > 0) {
                locText = insertAfterKey(
                    locText,
                    baseKey,
                    newLines
                );
            }
        }
    }

    return locText;
}

